def minSquares(n):
    f = [0] + [n] * n
    squares = []
    k = 1
    while k * k <= n:
        squares.append(k * k)
        k += 1
    for m in range(1, n + 1):
        best = m
        for s in squares:
            if s > m:
                break
            if f[m - s] + 1 < best:
                best = f[m - s] + 1
        f[m] = best
    return f[n]
